// Worker entry: OpenNext handler plus (1) NFT preview PNGs rendered with resvg-wasm and (2) the Workers Cache API for public GET responses.
// (The Cache API only stores entries on a custom domain / route, not on *.workers.dev.)
// OpenNext (Next.js server bundle) is loaded lazily: /api/* game routes, images and cached pages never need it, and evaluating it dominates cold-start time.
let openNextPromise:Promise<any>|null=null;
// @ts-ignore generated by `opennextjs-cloudflare build`
const loadOpenNext=()=>openNextPromise||(openNextPromise=import('./.open-next/worker.js').then(m=>m.default));
const openNext={fetch:async(request:Request,env:any,ctx:ExecutionContext)=>(await loadOpenNext()).fetch(request,env,ctx)};
import {nftPreviewResponse} from './lib/nft-preview-cf';
import {apiRoute} from './lib/api-route';
import {ASSET_VERSION} from './app/generated/version';
import {AsyncLocalStorage} from 'node:async_hooks';

const PAGE=/^\/((agents|matches|runs|rounds)\/[^/]+|(arena|mint|collection|marketplace|convert|nibtoken|nibmarket|bounty|wars|challenges|leaderboard|profile|docs|about|privacy|terms))\/?$/;
const PREVIEW=/^\/api\/nft\/preview\/v2\/([^/]+)$/;
async function handle(request:Request,env:any,ctx:ExecutionContext):Promise<Response>{
  const url=new URL(request.url);
  // Canonical host is www: send the apex there (permanent redirect, path and query preserved).
  if(url.hostname==='nibtap.site'){url.hostname='www.nibtap.site';return Response.redirect(url.toString(),301);}
  if(request.method==='GET'||request.method==='HEAD'){
   // Browsers ask for /favicon.ico: serve the SVG icon straight from the assets binding (no Next.js render).
   if(url.pathname==='/favicon.ico'){const icon=await env.ASSETS.fetch(new Request(url.origin+'/favicon.svg'));return new Response(icon.body,{status:icon.status,headers:{'Content-Type':'image/svg+xml','Cache-Control':'public, max-age=86400, stale-while-revalidate=604800'}});}
   // Only / and /{agents,matches,runs,rounds}/<id> are pages. Everything else that is not a static asset (scanner probes such as /runner.mjs, /wp-login.php) gets a cheap 404 instead of a full Next.js render.
   if(!url.pathname.startsWith('/api/')&&!url.pathname.startsWith('/_next/')&&url.pathname!=='/'&&!PAGE.test(url.pathname))return new Response('Not found',{status:404,headers:{'Content-Type':'text/plain; charset=utf-8','Cache-Control':'public, max-age=300'}});
  }
  if(request.method==='GET'){
   const m=PREVIEW.exec(url.pathname);
   if(m)return cached(request,ctx,()=>nftPreviewResponse(decodeURIComponent(m[1]),async()=>new Uint8Array(await (await env.ASSETS.fetch(new Request(url.origin+'/fonts/roboto-mono.ttf'))).arrayBuffer())));
  }
  // The game API is framework-independent (Request -> Response), so it bypasses Next.js/OpenNext. Card images (/api/card/*) still need Next's ImageResponse.
  if((request.method==='GET'||request.method==='POST')&&url.pathname.startsWith('/api/')&&!url.pathname.startsWith('/api/card/')&&!url.pathname.startsWith('/api/nft/preview/')){
   if(request.method==='GET')return cached(request,ctx,()=>apiRoute(request));
   return apiRoute(request);
  }
  if(request.method==='GET'&&url.pathname.startsWith('/api/'))return cached(request,ctx,()=>(openNext as any).fetch(request,env,ctx));
  if(request.method==='GET'&&(url.pathname==='/'||PAGE.test(url.pathname))&&!request.headers.has('Authorization'))return cachedPage(request,ctx,()=>(openNext as any).fetch(request,env,ctx));
  const page:Response=await (openNext as any).fetch(request,env,ctx);
  // OpenNext marks prerendered HTML s-maxage=1 year. Page HTML references hashed chunks that change every deploy, so make it revalidate instead of risking a stale shell pointing at deleted /_next chunks.
  if((page.headers.get('Content-Type')||'').startsWith('text/html')&&/s-maxage/.test(page.headers.get('Cache-Control')||'')){const h=new Headers(page.headers);h.set('Cache-Control','public, max-age=0, must-revalidate');return new Response(page.body,{status:page.status,statusText:page.statusText,headers:h});}
  return page;
}
export default {
 fetch(request:Request,env:any,ctx:ExecutionContext):Promise<Response>{
  // Chain-read caching only for GET API requests (never for POSTs that may verify receipts or build transactions).
  if(request.method==='GET'&&new URL(request.url).pathname.startsWith('/api/'))return readScope.run({ctx},()=>handle(request,env,ctx));
  return handle(request,env,ctx);
 },
};
async function cached(request:Request,ctx:ExecutionContext,render:()=>Promise<Response>):Promise<Response>{
 const cache=(caches as any).default as Cache;
 const key=new Request(request.url,{method:'GET'});
 const hit=await cache.match(key);if(hit)return hit;
 const response=await render();
 let cc=response.headers.get('Cache-Control')||'';
 if(response.status===200&&/(s-maxage|max-age)=[1-9]/.test(cc)&&/public/.test(cc)&&!response.headers.has('Set-Cookie')){
  // The zone's "Browser Cache TTL" (default 4h) is applied to cacheable responses that have no max-age, which would leave browsers holding live data for hours. Make browser freshness explicit.
  if(/s-maxage/.test(cc)&&!/(^|[ ,])max-age=/.test(cc)){cc=cc.replace(/^public,?\s*/,'public, max-age=0, ');const h=new Headers(response.headers);h.set('Cache-Control',cc);const fixed=new Response(response.body,{status:response.status,statusText:response.statusText,headers:h});ctx.waitUntil(cache.put(key,fixed.clone()));return fixed;}
  ctx.waitUntil(cache.put(key,response.clone()));
 }
 return response;
}
// ---- Shared edge cache for chain reads --------------------------------------------------------------
// Every isolate used to repeat the same BNB Chain eth_call/eth_getLogs reads. For GET API requests only, identical JSON-RPC reads are
// cached in the colo's Cache API for a few seconds, so concurrent visitors share one upstream call. Writes/receipts/POSTs are never cached.
const readScope=new AsyncLocalStorage<{ctx:ExecutionContext}>();
const nativeFetch=globalThis.fetch.bind(globalThis);
const RPC_TTL:Record<string,number>={eth_call:8,eth_chainId:3600,eth_getLogs:10};
async function sha(text:string){const d=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)));return Array.from(d.slice(0,16),b=>b.toString(16).padStart(2,'0')).join('');}
globalThis.fetch=async function(input:any,init?:any):Promise<Response>{
 const scope=readScope.getStore();
 if(!scope||!init||init.method!=='POST'||typeof init.body!=='string'||!(typeof input==='string'?input:input?.url||'').startsWith('https://bsc-'))return nativeFetch(input,init);
 let ttl=0;try{const body=JSON.parse(init.body);const calls=Array.isArray(body)?body:[body];ttl=Math.min(...calls.map((c:any)=>RPC_TTL[c?.method]||0));}catch{}
 if(!ttl)return nativeFetch(input,init);
 const cache=(caches as any).default as Cache;
 // JSON-RPC ids are per-call counters; normalise them out of the key and restore the caller's id on a hit.
 const parsed=JSON.parse(init.body);const norm=JSON.stringify(Array.isArray(parsed)?parsed.map((c:any)=>({...c,id:0})):{...parsed,id:0});
 const key=new Request('https://www.nibtap.site/__rpc/'+await sha(norm),{method:'GET'});
 const hit=await cache.match(key);
 if(hit){try{const data:any=await hit.json();const fix=(r:any,c:any)=>({...r,id:c.id});const out=Array.isArray(parsed)?parsed.map((c:any,i:number)=>fix(data[i],c)):fix(data,parsed);return new Response(JSON.stringify(out),{status:200,headers:{'Content-Type':'application/json'}});}catch{}}
 const res=await nativeFetch(input,init);
 if(res.ok){try{const text=await res.clone().text();const data=JSON.parse(text);const bad=(Array.isArray(data)?data:[data]).some((r:any)=>!r||r.error||!('result' in r));if(!bad)scope.ctx.waitUntil(cache.put(key,new Response(text,{headers:{'Content-Type':'application/json','Cache-Control':'public, max-age='+ttl}})));}catch{}}
 return res;
};
// ---- HTML pages: edge cache with stale-while-revalidate, keyed by deploy version ---------------------
const HTML_FRESH=60,HTML_STALE=86400;
async function cachedPage(request:Request,ctx:ExecutionContext,render:()=>Promise<Response>):Promise<Response>{
 const cache=(caches as any).default as Cache;
 const url=new URL(request.url);url.search='';url.searchParams.set('__v',ASSET_VERSION);
 const key=new Request(url.toString(),{method:'GET'});
 const out=(r:Response,state:string)=>{const h=new Headers(r.headers);h.delete('x-cached-at');h.set('Cache-Control','public, max-age=0, must-revalidate');h.set('x-edge-cache',state);return new Response(r.body,{status:r.status,headers:h});};
 const refresh=async()=>{const r=await render();if(r.status===200&&(r.headers.get('Content-Type')||'').startsWith('text/html')){const h=new Headers(r.headers);h.set('Cache-Control','public, max-age='+HTML_STALE);h.set('x-cached-at',String(Date.now()));h.delete('Set-Cookie');await cache.put(key,new Response(r.clone().body,{status:200,headers:h}));}return r;};
 const hit=await cache.match(key);
 if(hit){const age=Date.now()-Number(hit.headers.get('x-cached-at')||0);if(age>HTML_FRESH*1000)ctx.waitUntil(refresh().catch(()=>{}));return out(hit,age>HTML_FRESH*1000?'STALE':'HIT');}
 const r=await refresh();return out(r,'MISS');
}
